		["Башал'Аран"] = {
			["Астерион"] = {
				["Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на ее след."] = 955,
				["Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, ты сможешь ее добыть, то ты почти откроешь дверь моей темницы. Мне не сдержать слез..."] = 956,
				["Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорожденных. В Амет'Аране синий огонь. В этом огне печать может быть уничтожена. Будь осторожнее в тех руинах, $n..."] = 957,
