		["Башня Алталакса"] = {
			["Балтул Удар Тени"] = {
				["Группа чернокнижников обосновалась вокруг и внутри башни. Я хотел было вернуться в Аубердин и доложить Однако я предостерегаю вас от попытки вторгнуться в саму башню: чернокнижники, засевшие там, гораздо сильнее!"] = 966,
				["За всю проделанную вами работу вы заслужили хорошую награду. Возвращайтесь к Делгрену и скажите ему, Атрикус Нарассин лежит, сраженный вашей рукой, а клан Темной Нити сокрушен, и остатки его рассеяны."] = 981,
				["Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от Ясеневом лесу. Поторопитесь – я боюсь, что угроза клана Темной Нити растет с каждым часом."] = 967,
				["Понятно. Ну если то, о чем вы говорите, – правда, то сейчас самое время нанести его окружает множество сильных колдунов, гораздо более опасных, чем те, с кем вы встречались ранее."] = 1143,
			},
			["Делгрен Очиститель"] = {
				["Илкруд Магтрулл. Да, я знаю о нем. Это могучий орочий чернокнижник, который поселился в Святилище досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться."] = 973,
				["Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я там, $n, от вида кровавых храмов сатиров содрогнется даже $Gтакой закаленный:такая закаленная:c; $c, как ты."] = 1140,
				["Письмо Балтула приводит меня в ужас. Этот клан Темной Нити – сущее бельмо у меня думаю, заключается секрет силы клана. Принеси его мне, а уж я сумею разгадать его тайну."] = 970,
				["Прежде чем встретиться с Атрикусом, разумно было бы тебе посоветоваться с Балтулом. Не сомневаюсь, что Балтулом. Не сомневаюсь, что он неусыпно следил за башней и может знать о недавних событиях."] = 1167,
			},
			["Часовой Элисса Звездный Ветер"] = 965,
		},
