		["Безрассудство Аругала"] = {
			["Далар Ткач Рассвета"] = {
				["Для меня загадка, каким образом Аругал вообще был принят в Кирин Тор. Его знания касательно не сумел их заполучить. Добудьте для меня ту из этих книг, которая называется \"Зелье Аругала\"."] = 422,
				["Изучив деятельность Аругала я понял, что мои наихудшие подозрения верны. Старый хрыч был недостоин даже исследований количества их заколдованных наручей. Эти злобные создания обитают к северу и к востоку отсюда."] = 423,
				["Мне потребуется больше времени на раскрытие темных тайн чар Аругала,чем я думал. Но тем временем голову с плеч пораженному скверной старшине рудника Мрачнону Белесому. После его смерти рудник будет нашим."] = 424,
				["По мере того, как растет мое понимание магии Аругала, растет и мое презрение к этому кандалов, надетых на крестьян Аругалом. Принеси мне 6 заколдованных кандалов из деревни Погребальных Костров, $N."] = 99,
