		["Битва за Хилсбрад"] = {
			["Верховный палач Дарталия"] = {
				["В Хилсбраде царит паника. Думаю, он скоро падет. Но мы не должны ослаблять натиск, пока документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации."] = 532,
				["Дворфы пришли на помощь людям? Проклятые мелкие твари! Что ж, испытаем силу так называемого Альянса. цель этой битвы – осадить Дун Гарок, $c. Глава дворфов, капитан Железная Гора, должен умереть."] = 541,
				["Когда говоришь со мной, стой по стойке \"смирно\", $c. Я нахожусь под прямым командованием Вариматраса. Устрой налет на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца."] = 527,
				["Люди Хилсбрада оказывают нам неожиданное сопротивление. Кажется, проблема в кузнеце, снабжающем горожан оружием. Необходимо прервать партией железа. Нам оно пригодится, когда мы одержим победу над Хилсбрадом и нападем на Южнобережье."] = 529,
				["Поскольку ты $gпроявил:проявила; немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное Пусть его прочитает высшее командование. Отнеси мое письмо Вариматрасу в Подгород. Можешь гордиться собой, $c."] = 550,
				["Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно. Наши стражи смерти докладывают и отыщи там трусливых крестьян. Рази их направо и налево во имя Темной Госпожи. $gСвободен:Свободна;!"] = 528,
				["Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса. Более того, львиную долю руды, убей штейгера, человека по имени Бондс. Убей и его горняков. Альянс надолго запомнит этот урок."] = 539,
			},
