				["Без благословения Алекстразы Связующей Жизнь и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном. Странные твари их в Дарнасс. Отнеси их к Фэндралу Оленьему Шлему, ты найдешь его в роще друидов."] = 935,
				["К юго-востоку от входа в Дарнасс, на берегу Арлитириэнских прудов есть еще один лунный колодец. большей злобности фурболгов Кривой Сосны. Будь начеку во время поисков колодца и держи оружие наготове."] = 933,
				["Но не все было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне."] = 934,
				["Сначала позволь поведать тебе, какая стоит перед тобой задача. Друиды Дарнасса пользуются водой из лунных ты выполнишь это задание, я продолжу свой рассказ с момента, на котором его прервал Тенарон..."] = 929,
			},
			["Тенарон Хватка Бури"] = {
				["Пришло время тебе отправиться на поиски своей судьбы, $n. Но чтобы подготовиться к встрече с Тебе нужно исполнить важное поручение. Принеси мне воды из лунного колодца к северу от Альдрассила."] = 921,
				["Я мог бы поведать тебе еще многое о лунных колодцах и о Тельдрассиле, однако тебе тебе не сходить с дороги, $n, – в последнее время в лесу появились опасные существа."] = 928,
