				["Может, ты $gзаметил:заметила; крупных воргенов, бродящих по лесу в компании тенеткачей? Судя по всему, большую юго-западе от города. Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться. Будь $gосторожен:осторожна;."] = 221,
				["На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом. Выступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду."] = 173,
