			["Драз\\'Зилб"] = {
				["Выводок Ониксии расползся по всей Земле Драконов. Нельзя допустить, чтобы и остальные ее отродья вылупились продолжать плодиться драконы. А что касается Мок'Морокка... касательно этого червя у меня есть особые планы."] = 1172,
				["Деревня Каменный Молот была захвачена выводком Ониксии. Но почему дочь великого дракона Смертокрыла вторглась в Неужели только для того, чтобы уничтожить небольшое поселение огров? Предупреди Мок'Морокка. Нельзя сидеть сложа руки!"] = 1170,
