			["Кальвин Монтеччи"] = {
				["Что? ЧТО?! Денег хочешь? Не должен я тебе никаких денег. Письмо? Какое письмо? Может, еще Письмо? Какое письмо? Может, еще и подеремся? Ну, $gприятель:подружка;, давай! Вот еще, деньги я должен..."] = 590,
				["Эй, $gприятель:подруга;! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и крайней мере, ты $gдолжен:должна; туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу."] = 8,
