				["У меня нет сомнений, что в стенах Стромгарда засел могущественный чернокнижник. Время от времени, используя по разрушению реликвии и прослежу, чтобы ее мощь больше не использовалась для осквернения этой земли."] = 673,
				["Я почувствовал что-то странное в воздухе... ощущение, будоражащее мою кровь. У меня возникли подозрения. Я но я не рискую возвращаться в поместье. Можете ли вы принести мне оттуда несколько амулетов?"] = 671,
