		["Зов"] = 8315,
		["Зов Воды"] = {
			[""] = {
				["Много воды утекло со времени последнего испытания. Ты $gпроявил:проявила; немало упорства в учении и пришло лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $N."] = 2986,
				["Отзвучали последние слова заклятья, и вас ослепляет вспышка света. Звуки капель, падающих на пламя, стихают, капель, падающих на пламя, стихают, и вас переполняет радость: ведь оскверненные духи вокруг вас уничтожены."] = 100,
				["Похоже, ты $gготов:готова; к новому испытанию, $N. Ты $gпроявил:проявила; немало упорства в учении, и пришло лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $N."] = 2985,
			},
			["Брин"] = {
				["Возьми этот бурдюк и ступай в густой лес, который ночные эльфы зовут Ясеневым. Он находится островке, есть маленький фонтан. Прежде чем возвращаться к Ислен, принеси мне воду из этого источника."] = 1534,
				["Давным-давно мы с несколькими спутниками отправились в предгорья Хилсбрада. Нам пришлось отбиваться от навязчивых людей, света в царстве тьмы. Набери воду из этого источника в этот бурдюк и принеси мне."] = 1536,
				["Чтобы обрести понимание и получить от меня сапту, тебе предстоит отыскать чистейшую воду. Принося мне эту жизнь у других. Начнем с малого: ниже моего домика есть пруд с драгоценной влагой."] = 1535,
			},
			["Ислен Заклинатель Воды"] = {
				["На побережье Серебряного Бора, к западу от Гробницы, находится святилище, оскверненное чумой. Духи перестали разговаривать Принеси мне доказательство того, что мое задание выполнено, и в награду я дам тебе тотем."] = 63,
				["Первым делом ты $gдолжен:должна; понять, что вода означает возрождение. Вода течет, разрушает и очищает все получить сапту воды, отыщи Брин в южной части Степей. На ее дом постоянно нападают иглогривы."] = 1530,
			},
			["Ксаварик"] = 1529,
			["Низшее воплощение воды"] = 96,
			["Огнир хранитель Огня"] = 1528,
		},
		["Зов Воздуха"] = {
			["Ксаварик"] = 1532,
			["Огнир хранитель Огня"] = 1531,
		},
		["Зов Земли"] = {
			["Канага заклинатель земли"] = {
				["Сапта – это напиток, который связывает душу со стихией. Сама магия растворена в нем. И к юго-западу отсюда. Он находится в конце Потайной тропы. Выпей там сапту, а дальше... увидишь!"] = 1517,
				["Что ж, $c, пора! Ты $gнабрался:набралась; сил, твой дух стоек, как сама Земля. А то, и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твое будущее."] = 1516,
			},
			["Низшее воплощение земли"] = {
				["Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы ты станешь единым целым с землей – чти же ее, и она будет чтить тебя."] = 1521,
				["Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы ты станешь единым целым с Землей – чти же ее, и она будет чтить тебя."] = 1518,
			},
			["Провидица Воронье Перо"] = {
				["Время настало, $gюный:юная: c; $c. Тело твое возмужало, а дух закалился, как сама земля. Я они используют в своих ритуалах. Возвращайся ко мне, когда соберешь достаточно мази для изготовления зелья."] = 1519,
				["Сапта – это напиток, призванный объединить твой дух со стихиями. Сотворенное с помощью магии зелье священном месте и более нигде. Найди шаманское святилище к востоку отсюда и выпей сапту там."] = 1520,
			},
