				["Значит, наш добрый король решил построить памятник в честь солдата по имени Салли Баллу? И нужен самый лучший камень. Отправляйся на Холм Дарроу в Хилсбрад и привези мне альтеракского гранита."] = 689,
			},
			["Король Магни Бронзобород"] = 686,
		},
		["Королевский сюрприз"] = 4363,
		["Королевское право"] = 7261,
		["Король Гиблой Чащи"] = 6621,
		["Корона Воли"] = {
			["Мелизара"] = {
				["Лейтенанты Муг'Тола мертвы, и нам остается только убить его самого и забрать корону Воли. Нет Отыщи Муг'Тола и принеси мне его голову вместе с короной. Положим конец сопротивлению Раздробленного Хребта."] = 520,
				["Муг'тол и огры Раздробленного Хребта захватили руины Альтерака. Наказать их всерьез будет нелегко, если не нелегко, если не проредить сначала ряды огров. А уж потом мы продолжим. Ясно? Отлично. Выполняй."] = 518,
				["Остается отнести корону Воли Шарлиндре в Подгород. Она уж передаст ее леди Сильване. Но даже даже не думай воспользоваться ей в личных целях, $N. Пусть тебе послужит уроком судьба Муг'Тола."] = 521,
				["Тарг, Навозер и Гломмус – лейтенанты Муг'Тола. Они верны ему, хотя кто там разберет, что верными. Принеси мне их головы, $n, и нам останется отрубить башку Муг'Толу вместе с короной."] = 519,
			},
