		["Ларион и Майджин"] = 4145,
		["Левая часть амулета Лорда Вальтхалака"] = {
			["Бодли"] = {
				["Мой друг Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пыткам воевода Вун. Призрачные убийцы пробрались к нему и убили его на глазах у Вуна."] = 8966,
				["Наши бывшие соратники, брат с сестрой Сотос и Джариен, решили присоединиться к Алому ордену. Они было, нам нужна эта часть амулета, и мы... то есть ты $gдолжен:должна; будешь ее забрать."] = 8968,
				["Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее нас дошли слухи, что у святилища Элдретарра Изалиен попала в засаду, которую устроил Алззин Перевертень."] = 8967,
				["Теперь, когда у нас есть все, что нужно для ритуала призыва, осталось решить, кого именно укрылся от призрачных убийц. Они прикончили его на глазах у Раса Ледяного Шепота, его хозяина."] = 8969,
			},
		},
		["Легенда о Корраке"] = 7181,
		["Легенда о Сталване"] = {
			[""] = {
				["Внутри ящика вы находите много разных вещей: пыльные фамильные ценности, портрет, несколько охотничьих трофеев и старые книги. Уже на самом дне, под глиняной вазой, вам попадается страница, вырванная из дневника."] = 74,
				["Вы находите в старом сундуке пыльное неотосланное письмо. Вы находите в старом сундуке пыльное неотосланное письмо."] = 68,
			},
			["Клерк Далтри"] = {
				["$N, немедленно сообщи командиру Чернодрев, что почерки совпадают! Ее подозрения подтвердились! $N, немедленно сообщи командиру Чернодрев, что почерки совпадают! Ее подозрения подтвердились!"] = 97,
				["Боже мой! Сразу и не заметил. В журнале, точно под первым адресом Сталвана, написан еще вычеркнутый. Похоже, он направлялся в таверну \"Гордость льва\" в Златоземье. Можешь поискать сведения там, $N."] = 69,
				["Сталван, значит? Дай-ка погляжу в журнал. Сталван... Сталван... Ну-ка... А, вот он! У меня есть Окажи любезность, дай знать, если выяснишь что-либо об этом типе. Записи должны содержаться в порядке."] = 67,
			},
			["Командир Алтея Чернодрев"] = {
				["Сталван Мистмантл вел порочную жизнь. От его руки погибли многие невинные люди. Несомненно, он виновен именно ее предчувствие позволило нам раскрыть это темное преступление. Благодаря ей в Темнолесье стало безопаснее."] = 98,
				["Я давно присматриваюсь к этому Сталвану. Но если эта страница написана той же самой рукой, по различению почерков. Покажи ему эту страницу, проверь, совпадает ли почерк с росписью в журнале."] = 80,
			},
			["Мадам Ева"] = 66,
			["Маршал Хаггард"] = {
				["Когда я только приехал сюда, в сундуке на втором этаже лежала кипа пергаментов. Как-то раз выцветшая страница с интересными записями. Принеси ее мне, и я помогу тебе по мере сил."] = 75,
				["Я знаю, кто мог бы тебе помочь. Когда я служил в страже Штормграда, мы порой Ее хозяин Смиттс всегда был знатоком преданий. Покажи ему эту страницу, посмотрим, что он скажет."] = 78,
			},
			["Управляющий Фольсом"] = 72,
			["Хозяин таверны Смиттс"] = 79,
			["Хозяин таверны Фарли"] = 70,
