			["Менара Расщепительница Бездны"] = {
				["Осталось отыскать три составляющих, $N, и твое одеяние будет готово. Во-первых, нить из чистого золота, души, созданный тобой. Собрав все составляющие, возвращайся в башню, и я закончу работу над одеянием."] = 4784,
				["Первым делом я помогу тебе создать одеяние. Ты принесешь мне несколько необходимых составляющих, а уж еще лучше сделать их самому, но это сложно. Короче, для начала принеси мне эти одеяния."] = 1796,
				["Следующее задание не сложнее первого, но тебе все равно потребуется помощь. Для вышивки мне нужна с радостью спрядет для тебя нить. Золотые слитки могут изготавливать опытные горняки. Обратись к ним."] = 4781,
				["Следующие материалы можно найти в Пустошах, далеко на западе от Степей, за Когтистыми горами. Там камень Преисподней от младших инферналов Поля Маннорок. И то, и другое понадобится для создания одеяния."] = 4783,
