				["Мастер Гелькулар почти превратился в Короля Мертвых, когда его ритуальное логово в холмах обнаружила разъяренная понадобится жезл Гелькулара. Его ритуальное логово захватили йети. Жезл несомненно находится у одного из них."] = 552,
