				["Дружина Стальгорна оказалась чрезвычайно полезным союзником в наших битвах в Силитусе. К сожалению, по пути много припасов и оборудования. Добудь партию оружия и доставь ее Джанеле Твердомолот к Улью Зора."] = 8781,
