				["Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах."] = 369,
				["Пока ты $gсобирал:собирала; для меня образцы, я провел исследования и обнаружил, что для должного распространения мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу."] = 368,
				["Страж смерти сообщил, что недавно был захвачен еще один дворф-горный пехотинец. Стражи смерти обычно сажают я приготовил? В нем есть небольшая примесь того, что Темная Госпожа готовит для всего Азерота."] = 492,
