		["Осквернитель душ"] = {
			[""] = 1480,
			["Маурин Костолом"] = {
				["Кристалл оракула нам подойдет. Их делают наги для своих оракулов. К северо-западу отсюда, на побережье, осторожнее, и постарайся убраться оттуда побыстрее. А когда вернешься, мы попробуем отыскать этого лорда Азретока."] = 1482,
				["Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты. Однако, если он действительно попавшегося, а тенелова из племени Ярой Ненависти. Ищи их в древних развалинах на северо-востоке Пустошей."] = 1481,
				["Это существо куда опаснее, чем мне казалось! Неудивительно, что Таката сомневается, что мне удастся его демона, если он разрешит, но особо не настаивай. Пусть думает, будто это его собственная идея."] = 1484,
