		["Основной источник"] = {
			["Дендрит Блеск Звезд"] = {
				["Вершина Багрового Тумана, что к северо-западу от Перекрестка – самый вероятный источник распространения этой отравы. и просил нашей помощи, и ты будешь работать вместе с ним над искоренением этой заразы."] = 6127,
				["Водопад Скалистый на Темном Берегу – основной источник питьевой воды для всего региона, но теперь в Аубердин. Именно она просила нашей помощи, и ты поможешь ей разобраться с этой заразой."] = 6122,
