		["Особая посылка для Гаксима"] = 1077,
		["Особые войска"] = 574,
		["Останки Трея Светогорна"] = 5385,
		["Останки морской твари"] = {
			[""] = {
				["Останки гигантского крепкозуба – намного больших размеров, чем можно было бы ожидать на Темном Берегу, некоторая часть костей уже начисто обглодана, останков еще достаточно, чтобы набрать образцов для Гвеннид Блай'Леггонд."] = 4723,
				["Останки животного, похожего на гигантского крепкозуба, лежат, вынесенные на отмель в скалистой Сумрачной Излучине. Этот Хотя туша животного уже потеряла целостность, останков достаточно, чтобы найти подходящие образцы для Гвеннид Блай'Леггонд."] = 4733,
				["Полуразложившиеся тело твари, похожей на огромное морское млекопитающее, лежит на берегу. Группа мурлоков, более сильных, обосновалась вокруг погибшего создания. Останков достаточно, чтобы отобрать образцы костей, которые можно отнести Гвеннид Блай'Леггонд."] = 4730,
				["Растерзанные останки того, что на вид кажется похожим на гигантское морское млекопитающее, лежат на берегу. основательно растащили скелет, останков достаточно, чтобы найти подходящий образец костей для Гвеннид Блай'Леггонд в Аубердине."] = 4728,
			},
		},
		["Останки морской черепахи"] = {
			[""] = {
				["Вы наткнулись на останки морской черепахи, некоторое время назад выбросившейся на Темный Берег. Плоть ее обосновавшиеся неподалеку от останков. Однако вы можете набрать достаточное количество образцов, которые пригодятся Гвеннид Блай'Леггонд."] = 4722,
				["Вы обнаружили тело морской черепахи, выбросившейся на Темный Берег некоторое время назад. Оно почти дочиста что поселились вокруг останков. Однако, похоже, несколько подходящих образцов для Гвиннед Блай'Леггонд вы сможете отобрать."] = 4732,
				["Еще одни останки морской черепахи лежат прямо на берегу. К панцирю прикреплена упряжь. Скорее всего, Обследуя упряжь, вы обнаруживаете ящик со странными пометками. Может быть, Гвеннид Блай'Леггонд сможет что-то понять?"] = 4725,
				["Еще одни останки морской черепахи лежат у береговой линии. На панцире есть упряжь, которая еще жилищем. Обследуя упряжь, вы обнаруживаете ящик со странными пометками. Возможно, Гвеннид Блай'Леггонд сумеет что-то разобрать?"] = 4731,
				["Скелет морской черепахи лежит на песчаной отмели на севере Темного Берега. Мурлоки клана Серой Мглы черепахи осталось достаточно, чтобы взять образцы для Гвеннид Блай'Леггонд, проводящей расследование по поручению Храма Луны."] = 4727,
			},
		},
		["Останки на берегу"] = {
			["Гвеннид Блай\\'Леггонд"] = {
				["Громадные морские твари выбрасываются на пески Темного Берега и лежат там, пока не умирают. В Мглы. Не могли бы вы сходить туда и принести мне для изучения кости этой твари?"] = 3524,
				["Та тварь на берегу – не единственная на Темном Берегу. Вдоль побережья их еще много, найти и другие подобные останки. Если вы обнаружите что-то, обязательно принесите нам для дальнейших исследований!"] = 4681,
