		["Правая часть амулета Лорда Вальтхалака"] = {
			["Бодли"] = {
				["Мой товарищ Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пыткам воевода Вун. Призрачные убийцы пробрались к нему и убили его на глазах у Вуна."] = 8989,
				["Наши бывшие соратники Сотос и Джариен некогда решили вступить в ряды Алого ордена. Уходя, они было, нам нужна эта часть амулета, и мы... то есть ты... $gдолжен:должна; будешь ее забрать."] = 8991,
				["Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее нас дошли слухи, что у святилища Элдретарра Изалиен попала в засаду, которую устроил Алззин Перевертень."] = 8990,
				["Теперь, когда у нас есть все, что нужно для ритуала призыва, осталось решить, кого именно укрылся от призрачных убийц. Они прикончили его на глазах у Раса Ледяного Шепота, его хозяина."] = 8992,
			},
		},
		["Правда и только правда"] = {
			["Аптекарь Фаустин"] = {
				["Все прошло точно по плану. Теперь отнеси эту сыворотку правды стражу смерти Зредусу, и он отнеси эту сыворотку правды стражу смерти Зредусу, и он покажет, как ею... Правильно воспользоваться. Ха-ха!"] = 1388,
				["Я знаю подходящую сыворотку. Она обойдется с правдой именно так, как с ней следует обходиться. Пустошей. Эти гиганты редко болеют, а опухоли у них появляются еще реже. А теперь иди!"] = 1383,
			},
			["Страж смерти Зредус"] = {
