			["Опекун Илталайн"] = {
				["Мои приветствия, $N. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием прокормить. $gЮный:Юная:c; $c, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия."] = 456,
				["Сокращение численности молодых особей, обитающих в Тенистой долине – это неплохо для начала, $N, однако этих землях. Отправляйся в лес и убивай облезлых ночных саблезубов и щетинистых вепрей ради равновесия."] = 457,
			},
		},
		["Природные материалы"] = 3128,
		["Приручение зверя"] = {
			["Гриф Дикое Сердце"] = {
				["Возможно, тебе понравится животное, обладающее чем-то большим, чем просто грубая сила. Медведи-ледолапы – замечательные спутники опасности и получать опыт. Я также научу тебя призывать и отпускать животное по своему желанию."] = 6085,
				["Привет, $Gпарень:подруга;! Стало быть, хочешь узнать, как завести себе питомца? Что же, начнем. Когда доходит по сердцу. Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его."] = 6064,
				["Эти скальные вепри такие здоровенные – может, тебе хочется кого поизящнее? Ладушки, у меня есть тобой вепря. На, держи этот хлыст приручения. Посмотрим, придется ли тебе по душе снежный леопард."] = 6084,
			},
			["Дазалар"] = {
				["Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, его помощью ты сумеешь приручить чащобного тенетника. Приручи его и поупражняйся в своем охотничьем искусстве."] = 6063,
				["Природа изменчива, но на нее вполне можно положиться, $N. Она предсказуема в том, что никогда Поупражняйся в своем охотничьем искусстве. Таким образом ты начнешь понимать сходства и различия творений природы."] = 6101,
				["Тебе удалось приручить двух детей земли, и теперь тебе предстоит подружиться с обитателем неба. При будет набираться опыта. Я также научу тебя, как призывать и отпускать по желанию твоего питомца."] = 6102,
			},
			["Йо Колкая Грива"] = {
				["Для нас, тауренов, важно следовать традициям предков, сражаясь с могучими зверями. Одолевая их, мы вбираем приходится учиться, и этому тоже. Для начала возьми этот хлыст приручения; ступай, приручи равнинного долгонога."] = 6061,
				["Последним твоим заданием станет приручение жителя неба. Перепелятник – непростой противник, но зато отличный союзник с тобой набираться опыта. Я покажу тебе, как подзывать и отсылать его по собственной воле."] = 6088,
				["Твой дух полон огня, охотник, и ты с радостью встречаешь новые испытания. Следующее задание – действовать очень слаженно, как единый организм. Вот хлыст приручения, $n. Подчини себе охотника прерий, потренируйся."] = 6087,
			},
			["Тотар"] = {
				["Последнее животное, которое тебе придется приручить, – это бронескорп. Тебе придется частенько с ними сражаться. покажу тебе, как призывать его и отпускать на волю, когда в нем не будет надобности."] = 6082,
				["Разумеется, $n, питомец дает тебе большое преимущество в бою. Подчиняя себе живое существо, ты добавляешь Сен'джин и островов Эха. Воспользуйся хлыстом приручения, чтобы усмирить зверя, а потом потренируй свои навыки."] = 6083,
				["Умение подчинять природу своей воле – великое искусство. Ты $Gохотник:охотница;, и тебе следует научиться использовать от Колючего Холма. Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне."] = 6062,
			},
		},
