		["Пропавшие стражи смерти"] = {
			["Верховный палач Хадрик"] = {
				["Готовясь к нападению на крепость Темного Клыка, мы отправили на разведку двух стражей смерти. Они и помоги им, если сможешь. Это очень опасное и важное задание, $N. Не подведи нас."] = 1098,
				["Пару недель назад двое наших стражей смерти – Ран и Квинн Йорик, ушли на разведывательное первой целью была разведка на полях в северной части Серебряного бора. Начните свои поиски там."] = 428,
