		["Пропавший дипломат"] = {
			["Верховный маг Тервош"] = 1266,
			["Дашель Каменный Кулак"] = {
				["В Штормград приходили многие твои коллеги, $c, были среди них умные, были и круглые дураки, дураки, но подобных тебе нет, не было и не надо... Чего ты от меня хочешь?"] = 1447,
				["Ну... м-м... да... Я кое-что знаю о встрече на участке Эддла. Она произошла несколько недель пришел из Менетила. Его зовут Пронырой. Это все, что мне удалось узнать из запасного плана."] = 1247,
			},
			["Дозорный Бакус"] = {
				["О-ох, для обычной попытки ввести в заблуждение это слишком сложно. Отнесите этот документ Триасу, пусть что я о чем-то узнал и не поделился с ними, они могут меня запросто повесить."] = 1245,
				["Опять братство?! Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой. находится к югу от дороги из Западного Края как раз на входе в Сумеречный лес."] = 1244,
			},
			["Епископ Делавей"] = 1241,
			["Иллинг Триас"] = {
				["Вот что я об этом думаю... Дашель... Какой-то Дашель... Как его фамилия? Кулак! Дашель Каменный заговоре, как можно заключить по этим бумагам, то не расстанется с информацией по доброй воле..."] = 1246,
				["Йорген, ах ты старый мерзавец... Ну и что со всем этим делать? Ладно, я разберусь... а вы присматриваете за ним по моей просьбе – и он вам поможет, чем сможет."] = 1243,
				["Один из моих знакомых переехал в Болотину, в портовый город Менетил. Думаю, что он поможет в декларации ничего не говорится о том, что похитители собираются сделать с пленником после захвата."] = 1248,
			},
			["Йорген"] = 1242,
			["Командир Самаул"] = 1265,
			["Леди Джайна Праудмур"] = 1267,
			["Михаил"] = {
				["В начале каждого месяца стражи бухты Кул-Тираса получают жалованье и отправляются прочь из Терамора в верен леди Джайне, но если ты упомянешь при нем имя Эллинга, он должен стать... посговорчивее."] = 1264,
				["Значит, вас послал Эллинг? О, это повод десятикратно умножить мое гостеприимство! Просите всего, чего пожелаете, нашему разговору. На вашем месте я бы попробовал изловить его прежде, чем он уйдет отсюда."] = 1249,
