		["Противоядие для Иверрона"] = {
			["Дирания Серебряное Сияние"] = {
				["Мы могли бы помочь Иверрону: я знаю противоядие, которое нейтрализует действие яда. Но для него прудов. Последний ингредиент добыть сложнее всего. Это лимфа тех самых чащобных тенетников, что отравили Иверрона."] = 3521,
