		["Прохладное чувство юмора"] = {
			["Чудной снеговик"] = {
				["$n, с-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства! Т-только ос-стор-р-рожно! Это он с-сделал $n, отвезите его в Оргриммар, П-пастбищам Дымного Леса, и п-п-передайте им, что м-меня надо разморозить!"] = 6983,
				["$n, с-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства! Т-только ос-стор-р-рожно! Это он с-сделал $n, отвезите его в Стальгорн, П-пастбищам Дымного Леса, и п-п-передайте им, что м-меня надо разморозить!"] = 7043,
