				["В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на ему про обещанные награды. Ну, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!"] = 8957,
				["В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три ней об условленной награде. Я же ныне спокойно умру. Желаю удачи – она тебе понадобится!"] = 8951,
				["В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три условленной награде. Я же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!"] = 8952,
