				["Немедленно принимайся за сбор материалов для нейтрализации взрывчатки, $n. Паучий яд ты найдешь у пауков творение Черного Железа! Как только соберешь все материалы, сразу же возвращайся, и я подготовлю состав."] = 278,
				["Хвала небесам, что хоть кого-то волнует наша Дамба. Будто мало нам разрушенного моста Тандола и из клана Черного железа неподалеку от восточной части Дамбы. Разведай обстановку и возвращайся с уликами."] = 250,
				["Я только сегодня видел мятежников Черного Железа, которые тащили к Дамбе большую бочку. И рядом получилась нейтрализующая смесь. Скорее, возьми смесь и залей ее в бочку, пока не поздно. Торопись!"] = 280,
