				["От союзника Орды времен Второй войны, дракона Смертокрыла мы знаем, что два его лейтенанта, Чернохлыст узилище. Но Тогрун предал нас, забрав знак себе. Отправляйся в лагерь Бофф и отбери знак!"] = 782,
