			["Археолог Холли"] = {
				["Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога за помощью. Прошу тебя, отправляйся на юг и посмотри, все ли в порядке с геологом!"] = 729,
				["Так геолог хочет отослать эту таинственную окаменелость Лиге Исследователей в Дарнасс? Мне не хотелось бы Темных берегов без него. Вот, $n, отвезите эту таинственную окаменелость главному археологу Седоусу в Дарнасс."] = 741,
