		["Расследование Валарриэля"] = {
			[""] = 1465,
			["Валлариель Истребитель Демонов"] = {
				["Постарайся разыскать Далинду и Тираниса. Начни поиски с той самой крепости, о которой ты $Gговорил:говорила;, доставить ее домой. Целой и невредимой, по возможности. А вот Тираниса следовало бы сначала... проверить."] = 1438,
				["Приветствую тебя, $N. Я – Валарриэль. Я прибыл сюда, чтобы установить местопребывание двух пропавших торговцев назад они миновали Когтистые горы. Если найдешь их повозку, прошу тебя, немедленно дай мне знать."] = 1437,
