		["Раэна – санитар Ясеневого леса"] = {
			[""] = 1055,
			["Кролг"] = {
				["Возвращайся в свое племя и поведай им о нашей победе. Покажи им свой трофей и свое племя и поведай им о нашей победе. Покажи им свой трофей и насладись славой..."] = 1046,
				["Ночные эльфы стары, как время, но их надменность разрушает их собственный мир. А теперь еще к эльфам, но я не хочу зла их детям, так что сами должны обуздать своих."] = 1045,
			},
			["Раэна Волкопас"] = {
				["$N, один мой старый друг тоже помогает часовым здесь, в Ясеневом лесу, но он еще гор. Камень хранился там до того, как святилище было разрушено. Найди моего друга, $N, пожалуйста."] = 991,
				["Тебе придется провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл."] = 1024,
				["Увы, не могу сказать, что у него было на уме. Если он сказал правду о под порчу Мха Скверны. На мой взгляд, надо начать поиски к юго-востоку от озера Мистраль."] = 1030,
			},
			["Труп Терониса"] = 1023,
			["Шаэл\\'дрин"] = {
				["Вот собранный жезл, $N. Восстановить его было просто... Труднее будет найти святилище, в котором жезл долину. Как только ты окажешься там, положи жезл в святилище... а остальное сделает магия. Хе-хе."] = 1028,
				["Последний фрагмент жезла был отдан на хранение друидам Дор-Даниля. Я понятия не имею, где они этом думать. Когда найдешь последний фрагмент, принеси его мне, и я помогу тебе воссоздать жезл."] = 1027,
				["Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверен, она знает, куда сказать ей, что жезл воссоздан. Я уверен, она знает, куда тебе направиться дальше. Удачи, $N."] = 1029,
				["Хотелось бы мне, чтобы у тебя были более хорошие новости. Раэна права, я знаю о лощинку к западу от дороги близ границы Оскверненного леса... Сундук должен быть спрятан где-то там."] = 1026,
			},
		},
		["Реактивы для Поисковой корпорации"] = {
			["Крелдиг Унгор"] = {
				["А следующее по списку Скрытного Кудесника у нас... Погоди-ка... А, да, вот оно. Ну, не не с умирающего или дряхлого. Ох уж эти мне маги... вечно у них какие-то заскоки."] = 1459,
				["Одна из моих задач здесь – подбор реактивов для Скрытного Кудесника, гномского мага из Караноса. недалеко обитают, на востоке. Ты мне их сначала принеси, а потом мы займемся остальным списком."] = 1458,
				["Хочешь плату получить? Так за этим тебе придется вернуться в Стальгорн и потолковать со стариной всяко замолвлю за тебя словечко. Мне тоже не больно-то хочется торчать в этих самых Пустошах."] = 1467,
				["Это последнее в списке. Врать не буду, задание не из приятных; к тому же оно Простенькое такое заданьице, точно? Слушай, я тебе вот что скажу: если ты откажешься, я пойму."] = 1466,
