				["Вы касаетесь камня и слышите голос, звучащий в вашем сознании. \"Услышь мою мольбу, о $gсмертный:смертная;. сущности в моем логове – пусть магия очистит мое сознание от скверны и спасет меня!\""] = 3373,
				["Вы приводите в действие Камень клятвы и с его помощью Итар мысленно заговаривает с вами. Сделай это, $N, и дальше мы будем действовать вместе, чтобы освободить достойную многих жертв душу.\""] = 3374,
