		["Схватка с пантерой"] = {
			["Сэр С. Дж. Эрлгедин"] = {
				["А теперь задача потруднее. Если ты хочешь доказать, что $gдостоин:достойна; общаться с настоящими охотниками, убей ребятами не так легко справиться, они посильнее молодых зверей, с которыми тебе приходилось сталкиваться прежде."] = 191,
				["Если ты хочешь отправиться на охоту вместе с нами под предводительством Хеминга, докажи, что умеешь бойся, начнем с простого. Для примера убей 10 молодых пантер. Выследить их – только полдела..."] = 190,
				["Тебе почти удалось доказать, что ты $gвеликий охотник:великая охотница; на пантер. И все же остается же остается одна пантера по имени Баг'тира. Добудь ее клык, и мое уважение тебе обеспечено!"] = 193,
				["Усложняем задание. Настоящий охотник сможет одолеть даже тенебрюхих пантер, самых опасных в Тернистой долине. Докажи, 10 таких тварей. Если тебе покажется, что их трудно выслеживать, попробуй для начала убить одну..."] = 192,
			},
		},
		["Схватка с тигром"] = {
			["Ажек Руак"] = {
				["А ты учишься, $c. Посмотрим, как ты справишься со взрослыми кошками. На сей раз тебе ты справишься со взрослыми кошками. На сей раз тебе предстоит убить 10 тигров Тернистой долины."] = 186,
				["Вот твое последнее испытание. Мы уже много недель выслеживаем эту хитрую тигрицу, прозванную Син'Далл. Интересно, Син'Далл. Принеси мне ее лапу в доказательство своего подвига. Даже выследить ее – непростая задача."] = 188,
				["Когда я была маленькой девочкой, отец научил меня искусству охоты на тигров. Молодых зверей гораздо с простого. Молодые тигры часто забредают к лагерю экспедиции. Постарайся выследить и убить несколько зверей."] = 185,
				["Поднимем ставки. Докажи, что сможешь убить 10 старых тигров Тернистой долины. Справишься – и я в присутствии мастера Эрнестуэя. Старые тигры Тернистой долины неуловимы для врага и безжалостны в схватке."] = 187,
			},
		},
		["Схватка с ящером"] = {
			["Хеминг Эрнестуэй"] = {
				["А теперь я задам тебе задачку, посмотрим, придется ли она тебе по вкусу. Отправляйся в тебе по вкусу. Отправляйся в джунгли и добудь 10 ящеров-кнутохвостов. Увидим, хватит ли тебе пороху!"] = 195,
				["Значит, ты считаешь себя $gпревосходным охотником:превосходной охотницей;? Проверим. Ступай в джунгли и подстрели 10 ящеров дичью. И нет, я не скажу, где их искать! Первая половина испытания – поиски зверя."] = 194,
				["Ну, раз ты ходишь в джунгли как к себе домой, дай-ка я расскажу тебе о убей Тетис и принеси мне его коготь. Этот подвиг не удался еще ни одному охотнику!"] = 197,
				["Посмотрим, как ты справишься со следующим испытанием. Здесь живут хитрые ящеры, мы зовем их тропическими Убей 10 тропических ловцов, и я соглашусь, что из тебя еще выйдет $gнастоящий охотник:настоящая охотница;."] = 196,
