		["Флинт Тенемор"] = 6184,
		["Фолиант Божественности"] = {
			[""] = {
				["Во всех своих деяниях паладин должен быть достоин того Света, которому мы служим и который для паладина все это значит не меньше, чем искусство воина. Никогда не забывай об этом!"] = 1642,
				["Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы. Стремление значат для паладина не меньше, чем сила в сражении. Усвой же это и помни всегда."] = 1646,
			},
			["Азар Мощный Молот"] = 2997,
			["Брандар Железный Молот"] = {
				["Привет, $N. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морог, но когда паладины, когда приходит пора им узнать побольше о Свете и том, что от тебя ожидается."] = 2999,
				["Я вынужден прервать твое путешествие, $r. Из Штормграда пришла весть о том, что всех паладинов время изучения священных Фолиантов. Найди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света."] = 3681,
			},
			["Брат Вильгельм"] = 2998,
			["Газин Тенорм"] = {
				["Мы с Хензом добрались до острова Героев – он находится посреди Озера Каменных Столбов, в он там так и остался. Хенз, я имею в виду. Может, ты сумеешь помочь, $N?"] = 1786,
				["После того как Даториан ознакомится с этими бумагами, я передам их королевским советникам; однако прежде Твоя помощь поистине неоценима, $N. Надеюсь, это не последняя наша встреча. Я горжусь нашей дружбой."] = 1788,
			},
			["Даториан Ралл"] = {
				[""] = 1641,
				["Итак, $N, твоя задача – найти в Штормграде того, кто нуждается в помощи. Того, кто поговорим о твоем пути – а равно и о том, что значит быть паладином Света."] = 1643,
				["Прими этот знак Жизни, $N. Тебе удалось обрести милосердие и терпение: пришло время узнать, хватит Газином. Если сумеешь помочь ему, мы продолжим нашу беседу. Да пребудет с тобой извечный Свет!"] = 1781,
			},
			["Джон Тернер"] = {
				["Мы с женой держим в Штормграде сиротский приют, по большей части для детей, потерявших родителей удалось добыть еще немного льняной ткани для одежды, я бы смог, наконец, отправить посылку домой."] = 1648,
				["Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, $c."] = 1778,
			},
			["Лорд Грейсон Тенелом"] = 3000,
			["Майридон Кузнебой"] = {
				["Вижу, моя женушка прямо пышет гордостью. Я бы на твоем месте поскакал прямо к ней. буду искать тебя на боле боя против Плети и этой Черного Железа, когда придет пора."] = 1785,
				["Мы выслеживали дворфов Черного Железа, что окопались к югу от озера Хельмово Ложе. Мы знали, помощь. И я не успокоюсь, пока он ее не получит. Ты ведь поможешь ему, $N?"] = 1783,
			},
			["Нарм Фолк"] = 1784,
			["Стефани Тернер"] = {
				["Да будут благословенны эти несчастные! Многие из них потеряли родных во время набегов нежити... Мой бы у меня был лен на одежки малышам, их жизнь стала бы хоть немного легче..."] = 1644,
				["Я сегодня же отнесу это детям. Ты можешь не тревожиться, $c. Конечно, такие, как ты, $gдоказал:доказала;, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается. Доброго пути!"] = 1780,
			},
			["Тиза Боевой Горн"] = {
				[""] = 1645,
				["Твоя задача, $N, найти в Стальгорне кого-нибудь, кто нуждается в помощи. Того, кто чист душой паладином Света. Я останусь в храме до твоего возвращения. Мое наставничество нужно и другим паладинам."] = 1647,
				["Я хочу, чтобы ты $Gвзял:взяла; это, $N. Это называется знак Жизни. Ты $Gпоказал:показала; свое милосердие Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет."] = 1779,
			},
			["Хенз Фолк"] = 1787,
		},
		["Фолиант Доблести"] = 1794,
		["Фолиант Отваги"] = {
			[""] = 1649,
			["Даториан Ралл"] = {
				[""] = 1793,
				["Отлично! Отсутствие сомнений говорит о твоей готовности к испытаниям. Да будет так! В самом конце что Братство Справедливости захватило почти весь край. Дафне может понадобиться защита от злодеев. Отправляйся туда."] = 1650,
			},
			["Дафна Стилвелл"] = {
				["Бьюсь об заклад, они скоро вернутся – так что приготовься. В доме есть пистолет, я в прошлый раз. Моли Свет благословить тебя, потому что… Слышишь? Они идут! Укроемся за домом!"] = 1651,
				["Прошу, возвращайся к Даториану и передай ему, что теперь со мной все в порядке – волновался за меня. Ох, как я соскучилась по своему мужу! Жду не дождусь его возвращения..."] = 1652,
			},
		},
		["Фолиант благородства"] = {
