		},
		["Фолиант заговора"] = {
			["Йорах Аннисон"] = {
				["А! Вижу, наши вкусы сходятся. Поиски фолианта Заговора – достойное занятие. Знаешь ли ты, что в Стальгорн, но она потерялась при перевозке где-то на берегу озера к западу от Южнобережья."] = 1803,
				["Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет. Выбор на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине."] = 1805,
			},
			["Кром Крепкорук"] = {
				["Как же не хочется его выпускать из рук! Но ты его $gнашел:нашла; и, конечно же, раз их использовали орки клана Драконьей Пасти в Болотине. Я бы поискал у их заклинателей!"] = 1804,
