			["Провозвестник Мок\\'тардин"] = {
				["Орда должна узнать о силе магии джунглей и подчинить ее себе. Мне уже удалось добиться тебе не придется далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке."] = 570,
				["Остается лишь одно составляющее, и я смогу наложить чары на колье. К югу отсюда, близко воду Святого источника. Соблюдай осторожность. Сейчас его окрестности захватили наги. С ними тоже следует разобраться."] = 573,
				["Следующий компонент будет нелегко найти. Чтобы связать перья, когти и чистый клык, мне понадобится волшебный тебе понадобится убить нескольких зверей, чтобы понять, что именно мне нужно, но результат того стоит."] = 571,
