		["Эликсир Страдания"] = {
			["Аптекарь Лидон"] = {
				["Ах, еще один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с мельницей Таррен."] = 496,
				["Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания. Вот, эффект. Дай попробовать моему помощнику Ампи то, что Темная Госпожа готовит людям и созданиям Плети."] = 499,
			},
		},
		["Эликсир агонии"] = {
			["Аптекарь Лидон"] = {
				["За соседней дверью стражи смерти держат нескольких заложников-фермеров. Верховный палач Дарталия подозревает, что среди них Ох, повеселимся! Поставь гниющий бочонок на ковер у них в комнате. Чумной напиток для всех!"] = 524,
				["Новый день, новый эликсир. Если бы я тут командовал, я бы позволил Плети и жалким на востоке от реки и Южнобережья. Принеси мне 6 цветков Грязного Рыла для нового эликсира."] = 509,
				["Пришло время испытать новый эликсир. Но зачем же тратить хорошую, очень заразную болезнь на простых эти дворфики. Укради у них бочонок землекопского крепкого. Получив эту бочку, я устрою веселую вечеринку!"] = 517,
				["Я уже решил, что еще один день пройдет без капли радости, но тут ты $gпринес:принесла; веселье и начнется! Вот возьми этот состав Грязного Рыла и немедленно отнеси его мастеру-аптекарю Фаранеллу."] = 513,
