			["Аптекарь Лидон"] = {
				["Ах, ничто так не радует, как запах свежей крови в предгорьях! Смешаем капелюшку этого и ферму Хилсбрадских полей, что на юго-западе. Посмотрим, как мое \"угощение\" понравится собачке фермера Рея, Стэнли."] = 502,
				["О, $N... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит! крови горного льва можно создать великолепный напиток смерти. Принеси мне немного крови, и мы повеселимся."] = 501,
