				["Вот медовая брага готова вполне, Словно солнце играет в ее глубине! Мы в дубовый бочонок играет в ее глубине! Мы в дубовый бочонок ее разольем, А потом насладимся напитком вдвоем!"] = 53,
				["Где-то в южных краях, там, где вьется лоза Есть колодец с водой, что чиста как чиста как слеза. Бьет священной воды одинокий ручей, Будь же другом, скорей, отправляйся за ней!"] = 48,
				["Как прекрасна янтарная россыпь зерна! Словно жаром костра пропиталась она. Чтобы вышел наш пенный напиток пропиталась она. Чтобы вышел наш пенный напиток хорош, Ты ячмень мне добудь, кукурузу и рожь."] = 49,
				["Прочь дремота и лень! Встану я поутру, Замешаю зерно и в сусло разотру, Сплавить куб в сусло разотру, Сплавить куб перегонный - и будет добро! Только истинных свойств подойдет серебро."] = 50,
				["Хочешь, друг мой, на брагу взглянуть? - так и быть! Нам осталось лишь только ее лишь только ее процедить. Ветвь смоковницы даст нам немного угля, Будет хмельный напиток светлей янтаря!"] = 51,
