		["Барон Акванис"] = {
			["Дже\\'неу Санкри"] = {
				["This... this is quite the find, $N. You acquired this from Baron Aquanis in Blackfathom, bringing this to me. Please - take this, along with the Earthen Ring\\'s warmest regards."] = 909,
				["Ого... вот это находка, $N.\\n\\nГоворишь, ты добыл это из барона Акваниса в Черных Глубинах? Барон ты принес эту штуку мне. Прошу – прими это вместе с горячей благодарностью Служителей Земли."] = 6922,
			},
		},
		["Бартлби Пьянь"] = 1639,
		["Батранов волос"] = 1010,
		["Башал'Аран"] = {
			["Астерион"] = {
				["Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания."] = 954,
				["И правда... Грелли Башал\\'Арана не владеют тем, что я ищу... Однако недавно они были в времени, не моего. Для меня \"недавно\" простирается глубоко в прошлое, почти что в другую эру..."] = 955,
				["Мне трудно поверить, что вещь, которую я сейчас держу в руках, так долго держала меня будем тратить времени, $N. Когда печать будет уничтожена, я снова вольно смогу бродить по лесам."] = 956,
				["Я свободен, $N! Я могу собственными глазами видеть, какие изменения произошли с нашим миром... Я мой бывший хозяин, Атрикус, еще жив... Мое ощущение безнадежности вскоре уступит место мыслям о мести."] = 957,
			},
		},
		["Башмаки костяной косы"] = 9081,
		["Башмаки неустрашимости"] = 9039,
		["Башни и бункеры"] = {
			["Капрал Тика Кровавый Рык"] = 7101,
			["Сержант Дарген Грозовая Вершина"] = 7102,
		},
		["Башня Алталакса"] = {
			["Балтул Удар Тени"] = {
				["А, приятно снова свидеться, $N! Тут такие странные вещи творились, так что хорошо, что ты вопли. Вопли раскалывали воздух, а в землю порой били молнии. Что все это может значить?"] = 1167,
				["Большое спасибо, $n. Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников... невозможно сказать, в чем могут заключаться их планы. Больше нельзя тянуть. Нужно немедленно предупредить Делгрена."] = 966,
				["Тебя прислала Элисса? Это хорошо. У меня есть для нее тревожные вести, но не было хорошо. У меня есть для нее тревожные вести, но не было возможности передать их ей."] = 965,
				["Я надеюсь, что после смерти Атрикуса демонические силы в этом районе отступят. Я не сомневаюсь, вернутся, но тогда мы будем еще лучше подготовлены, чтобы встретить эту угрозу лицом к лицу."] = 1143,
			},
			["Делгрен Очиститель"] = {
				["Возможно, мы слишком долго терпели сатиров в этом лесу. Я поговорю с Элиссой насчет этого, сила Атрикуса сильно уменьшится. Мы должны воспользоваться этой возможностью и уничтожить его и его культ."] = 1140,
				["Если позволите, я вам скажу: слишком уж вы хорошо экипированы для $Gпростого посланца:простой посланницы;, не непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников."] = 967,
				["Ты сегодня $Gсвершил:свершила; великое дело, $n. Гордись – ты $Gсразил:сразила; могущественного чернокнижника. А теперь посмотрим, – ты $Gсразил:сразила; могущественного чернокнижника. А теперь посмотрим, что мы можем узнать из записок Илкруда."] = 973,
				["Хмм, этот камень души наполнен какой-то темной магией. Давай-ка посмотрим, что у него внутри... Хмм, этот камень души наполнен какой-то темной магией. Давай-ка посмотрим, что у него внутри..."] = 970,
				["Я знал, что вы возьметесь за это задание, $N. Я чувствую, вас ждут великие дела суждено исцелить многие недуги, что терзают наши земли. Примите мое благословение, $N, и этот дар."] = 981,
			},
		},
