				["Кости, которые вы принесли, принадлежат мирным морским млекопитающим, обитающим в водах, окружающих корни Тельдрассила. Им, узнаем. И снова спасибо вам за помощь. Пожалуйста, примите это вознаграждение от имени Храма Луны."] = 4730,
