		["Фолиант Божественности"] = {
			["Газин Тенорм"] = {
				["*кашляет* Рад встретить тебя, $R. Не обращай внимания на мои раны, жрец позаботится о старом скажу тебе, что случилось со мной и моим другом Хензом. Надеюсь, ты поможешь нам обоим."] = 1781,
				["Чудесно! Вам удалось, и вы спасли Хенза. Во истину Свет поддерживает вас, $N! Чудесно! Вам удалось, и вы спасли Хенза. Во истину Свет поддерживает вас, $N!"] = 1787,
			},
			["Даториан Ралл"] = {
				["А неплохо у нас тут в Штормграде, разве нет? Ты $gявился:явилась; как нельзя вовремя, $N. А неплохо у нас тут в Штормграде, разве нет? Ты $gявился:явилась; как нельзя вовремя, $N."] = 2998,
				["Добро пожаловать в Собор Света, $C. Добро пожаловать в Собор Света, $C."] = 3681,
				["Здесь, в Штормграде, я несу ответственность за путь паладина. Настало твое время, принять первый шаг ожидает тебя. Если ты это понимаешь, то ты добьешься большего успеха в достижении новых способностей."] = 1641,
				["Итак, ты быстро $gвернулся:вернулась;, а? И чего же ты $gдостиг:достигла; за это время? Итак, ты Удивительно, $N, ты действительно следуешь пути Света. Такая жертва будет обязательно вознаграждена в свое время..."] = 1780,
				["Снова приветствую тебя, $N. Как твои успехи в изучении фолианта божественности? Тогда ты $gдолжен быть тебя есть терпение, помочь другим, особенно тем, кто менее удачлив. Доказать что ты слуга Света."] = 1642,
				["Ты хорошо $gпоработал:поработала; сегодня, $N. Ты $gдолжен:должна; испытывать некоторую гордость за то, что ты $gсовершил:совершила;. с бедным Хензом. Будь, $N. Пусть твой путь, каким бы он не был, будет Светлым."] = 1788,
			},
			["Джон Тернер"] = {
				["ПРИЕМНЫЙ ДОМ СТО... ох, прошу прощения, я не собирался кричать на вас, $gсэр:миледи;. Меня зовут приходится платить, когда ты ответственен за рты, которые нужно накормить и спины, которые нужно одеть."] = 1647,
				["Это так прекрасно с вашей стороны, $N. Снова большое вам спасибо. Вы благородный человек, что вы благородны до самого конца. Берегите себя, и да охранит вас Свет в ваших путешествиях."] = 1648,
			},
			["Майридон Кузнебой"] = {
				["*кашляет* Приветствую тебя, $C. Не обращай внимания на мои раны, тут хороший жрец занимается лечением. Да, да, $C, я расскажу тебе, что случилось с Майридоном и его лучшим другом Нармом..."] = 1779,
				["Хаха! Тебе удалось! Ты $gспас:спасла; Нарма и $gнашел:нашла; доказательство, которое нужно моей жене, чтобы показать в них хоть что-то понимаю... не считая, конечно, моей жены. Прими снова мою благодарность, $N."] = 1784,
			},
			["Нарм Фолк"] = 1783,
			["Стефани Тернер"] = {
				["Ах, $N, благодарю, благодарю тебя! Детишки так рады будут, да и у меня будет побольше всегда верила, что в сердцах людей есть место милосердию. Да пребудет с тобой Извечный Свет."] = 1644,
				["О, привет, $gдорогой:дорогая;. Что, все ищешь приключений? Я так рада, что у тебя все в виду себя и своего мужа, конечно. Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей..."] = 1643,
			},
			["Тиза Боевой Горн"] = {
				["Здесь, в Стальгорне, я несу ответственность за путь паладина. Настало твое время, принять первый шаг ожидает тебя. Если ты это понимаешь, то ты добьешься большего успеха в достижении новых способностей."] = 1645,
				["Итак, ты быстро $gвернулся:вернулась;, а? И чего же ты $gдостиг:достигла; за это время? Итак, ты Удивительно, $N, ты действительно следуешь пути Света. Такая жертва будет обязательно вознаграждена в свое время.."] = 1778,
				["Привет тебе, $N. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла. Привет тебе, $N. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла."] = 2997,
				["Приветствую и добро пожаловать, $N. Приветствую и добро пожаловать, $N."] = 3000,
				["С возвращением, $N. Надеюсь ты $gнашел:нашла; время на прочтение книги? Тогда ты $gдолжен быть готов:должна есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь что ты слуга Света."] = 1646,
				["Ты $gсослужил:сослужила; Стальгорну великую службу сегодня, $N. Да благословят тебя все все добрые божества нашей эту силу мудро. И благодарю тебя от своего имени, имени супруга и от всего Стальгорна."] = 1785,
			},
			["Хенз Фолк"] = 1786,
		},
		["Фолиант Доблести"] = 1794,
		["Фолиант Отваги"] = {
			["Даториан Ралл"] = {
				["Вот мы и встретились снова. Я вижу, что дух твой бодр. Дом четы Стивеллов теперь тебя на их защиту – весьма скромная ответная услуга. Ты получишь награду за проявленную отвагу."] = 1652,
				["Ты $gдоказал:доказала;, что Свет с тобой, $N. Однако испытание еще не завершилось. Ты $gдоказал:доказала; что часть. Однако тебе еще многому надо научиться, и двери Собора Света для тебя всегда открыты."] = 1793,
				["Ты просишь испытать твою отвагу? Прекрасно! Для тебя в городе и в окрестностях найдется немало определить, достоин ли $c служить правому делу. Чувствуешь ли ты в себе готовность к испытанию?"] = 1649,
			},
			["Дафна Стилвелл"] = {
				["$N, мы победили! Благодарю тебя за помощь. Это было просто великолепно! Я и не думала, справиться с таким количеством врагов зараз. Твоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня..."] = 1651,
				["Здравствуй, $N. Я полагаю, что со всем этим оружием в руках ты хочешь либо захватить торопились, но сейчас они наверняка заметили тебя, а значит, будут здесь с минуты на минуту..."] = 1650,
