		["Фолиант благородства"] = {
			["Даториан Ралл"] = {
				["Ah, you\\'ve returned to the Cathedral, $n. Good. A lot has happened recently, and I prove worthy. Many treacherous enemies are about. I will need your help to stop them."] = 4485,
				["Congratulations, and may the Light protect you. Congratulations, and may the Light protect you."] = 1661,
