		["Фолиант заговора"] = {
			["Йорах Аннисон"] = {
				["Картография! Картинки, далекие от реальности. Они мне не нужны. \\n\\nКниги – повествование, описание! В них все свои карты на одну книгу о возвышении некромантии или сагу о торжестве Темной Госпожи."] = 1801,
				["Так-так-так! Что это у нас?\\n\\nНевероятно, $N. Я был уверен, что это невозможно, но вот я но вот я держу в руках фолиант Заговора.\\n\\nПозволь мне полистать его, пока ты не ушел."] = 1803,
			},
			["Кром Крепкорук"] = {
				["Фантастика! Теперь я могу присоединиться к тем немногим, кто читал эту книгу. Великий день для так, дай мне посмотреть ее, прежде чем ты уедешь... Уверен, что Страхад пришлет мне копию."] = 1802,
				["Фолиант заговора? Хмм... звучит знакомо. Я никогда не видел его здесь, и ранее, поверь, я которую я читал. Хмм... Ах, да!B Я видел посылание на нее, в библиотечном каталоге книг."] = 1758,
			},
			["Страхад Фарсан"] = {
				["Прекрасно! Фолиант заговора и три новехоньких жезла направления! Все что нам нужно! Давненько уже я направления! Все что нам нужно! Давненько уже я не видел $C, ставшего хозяином охотника Скверны."] = 1804,
				["Прекрасно! Фолиант заговора и три новехоньких жезла направления! Все что нам нужно! Давненько уже я направления! Все что нам нужно! Давненько уже я не видел $Cа, ставшего хозяином охотника Скверны."] = 1805,
